    data=urllib.request.urlopen(BASE_URL,context=context,timeout=30).read(131073)
    if hashlib.sha256(data).hexdigest()!=BASE_SHA:raise ValueError('Original runtime checksum mismatch; stopped')
    module=types.ModuleType('verified_nov23_base_starter');exec(compile(data,'verified-original-nov23-starter','exec'),module.__dict__)
    return module

